L3_1.m_CutScenProcessKey = 3
L3_1.m_CutScenID = 601
L3_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_QM"
L3_1.m_Talk_KOREA = "이쪽에서도 늑대의 움직임을 포착했습니다. 이걸로 첫 번째 시험 조건은 클리어되었군요."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "こちらからもオオカミの動きを捕捉しました。これで最初の試験は条件クリアですね。"
L3_1.m_Talk_ENG = "The Wolf's movement has been detected here as well. That clears the first condition for the test."
L3_1.m_Talk_TWN = "這邊也捕捉到了狼的動向。這樣第一項測試條件就完成了。"
L3_1.m_Talk_SCN = "这边也捕捉到了狼的动向。这样第一项测试条件就达成了。"
L3_1.m_Talk_DEU = "The Wolf's movement has been detected here as well. That clears the first condition for the test."
L3_1.m_Talk_FRA = "The Wolf's movement has been detected here as well. That clears the first condition for the test."
