L4_1.m_Talk_DEU = "I see."
L4_1.m_Talk_FRA = "I see."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@4#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 601
L5_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L5_1.m_Talk_KOREA = "역시 내 짐작대로 네가 이번 사건에 개입하고 있었나?"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "やはり私の推測通り、君が今回の件に介入していたのか？"
L5_1.m_Talk_ENG = "So, just as I suspected, you were involved in this incident after all?"
L5_1.m_Talk_TWN = "果然如我所料，你參與了這次事件嗎？"
L5_1.m_Talk_SCN = "果然如我所料，你参与了这次事件吗？"
L5_1.m_Talk_DEU = "So, just as I suspected, you were involved in this incident after all?"
L5_1.m_Talk_FRA = "So, just as I suspected, you were involved in this incident after all?"
L6_1 = {}
