L8_1 = {}
L8_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@6#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 601
L8_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L8_1.m_Talk_KOREA = "아시모프? 그럼, 고철 더미가 직접 접촉해왔다는 말씀인가요?"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "アシモフ？　あの鉄くずが直接接触してきたということですか？"
L8_1.m_Talk_ENG = "Asimov? So, are you saying Scraps contacted you directly?"
L8_1.m_Talk_TWN = "阿西莫夫？意思是廢鐵直接聯絡的嗎？"
L8_1.m_Talk_SCN = "阿西莫夫？那么，是说废铁堆直接接触过来了吗？"
L8_1.m_Talk_DEU = "Asimov? So, are you saying Scraps contacted you directly?"
L8_1.m_Talk_FRA = "Asimov? So, are you saying Scraps contacted you directly?"
L9_1 = {}
L9_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@7#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 601
L9_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L9_1.m_Talk_KOREA = "인지 왜곡 필터가 걸려 있는 모양이로군요. 제 눈에는 노이즈로 밖에 보이지 않습니다."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "認知歪曲フィルターがかかっているようですね。私の目にはノイズにしか見えません。"
L9_1.m_Talk_ENG = "It seems like there's an awareness distortion filter in place. All I can see is noise."
L9_1.m_Talk_TWN = "看起來是認知扭曲濾鏡在作怪。在我眼裡只看到噪音。"
L9_1.m_Talk_SCN = "看起来是认知扭曲滤镜在作怪。在我眼里只看到噪音。"
L9_1.m_Talk_DEU = "It seems like there's an awareness distortion filter in place. All I can see is noise."
L9_1.m_Talk_FRA = "It seems like there's an awareness distortion filter in place. All I can see is noise."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@8#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 601
L10_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L10_1.m_Talk_KOREA = "아마도 나 이외에는 자신의 모습이 드러나지 않도록 설정해 둔 모양이야."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "おそらく、私以外には自分の姿が見えないように設定してあるんだろう。"
L10_1.m_Talk_ENG = "It's probably set so that only I can see her."
L10_1.m_Talk_TWN = "可能除了我以外，其他人都設置，以免自己的樣子顯露出來。"
L10_1.m_Talk_SCN = "可能除了我以外，其他人都设置了不让自己的样子显露出来吧。"
L10_1.m_Talk_DEU = "It's probably set so that only I can see her."
L10_1.m_Talk_FRA = "It's probably set so that only I can see her."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@9#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 601
L11_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L11_1.m_Talk_KOREA = "깡통 주제에 신 행세를 하던 그 잘난 낯짝이 궁금했는데, 아쉽게 됐네요."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "神の真似事をするボロ缶とは果たしてどんな顔をしているのかと気になっていたのですが、残念ですね。"
L11_1.m_Talk_ENG = "I was curious to see the smug face of that tin can playing god. What a shame."
L11_1.m_Talk_TWN = "我本來還想看看那個自以為是神的鐵桶的嘴臉呢，真是可惜了。"
L11_1.m_Talk_SCN = "我本来还想看看那个自以为是神的铁罐子的嘴脸呢，真是可惜了。"
L11_1.m_Talk_DEU = "I was curious to see the smug face of that tin can playing god. What a shame."
L11_1.m_Talk_FRA = "I was curious to see the smug face of that tin can playing god. What a shame."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@10#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 601
L12_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L12_1.m_Talk_KOREA = "기본적으로 아시모프는 부끄럼쟁이거든."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "基本的にアシモフは恥ずかしがり屋なのでね。"
L12_1.m_Talk_ENG = "Asimov has always been shy."
L12_1.m_Talk_TWN = "基本上，阿西莫夫很害羞。"
L12_1.m_Talk_SCN = "基本上，阿西莫夫是个害羞鬼。"
L12_1.m_Talk_DEU = "Asimov has always been shy."
L12_1.m_Talk_FRA = "Asimov has always been shy."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@11#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 601
L13_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L13_1.m_Talk_KOREA = "이렇게 직접 대면하는 것도 상당히 이례적인 일이라고 할 수 있지."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "こうやって対面するのも、相当異例的なことだと言えるだろう。"
L13_1.m_Talk_ENG = "It's quite rare for her to meet with someone directly like this."
L13_1.m_Talk_TWN = "這樣直接面對面也是相當罕見的事。"
L13_1.m_Talk_SCN = "这样直接面对面也是相当罕见的事。"
L13_1.m_Talk_DEU = "It's quite rare for her to meet with someone directly like this."
L13_1.m_Talk_FRA = "It's quite rare for her to meet with someone directly like this."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@12#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 601
L14_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L14_1.m_Talk_KOREA = "……부끄럼쟁이라."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "……恥ずかしがり屋ですか。"
L14_1.m_Talk_ENG = "...Shy, you say."
L14_1.m_Talk_TWN = "害羞嗎？？"
L14_1.m_Talk_SCN = "……真是个害羞鬼。"
L14_1.m_Talk_DEU = "...Shy, you say."
L14_1.m_Talk_FRA = "...Shy, you say."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@13#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 601
L15_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L15_1.m_Talk_KOREA = "남들 앞에 나서기 싫어하는 게, 제가 아는 누군가와 꼭 닮았군요."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "人の前に出たがらないところは、私の知っている誰かとそっくりです。"
L15_1.m_Talk_ENG = "Not wanting to be seen reminds me of someone I know."
L15_1.m_Talk_TWN = "不喜歡在別人面前出頭，這和我認識的某個人很像呢。"
L15_1.m_Talk_SCN = "不喜欢在别人面前出头，这和我认识的某个人很像呢。"
L15_1.m_Talk_DEU = "Not wanting to be seen reminds me of someone I know."
L15_1.m_Talk_FRA = "Not wanting to be seen reminds me of someone I know."
