L17_1.m_Talk_KOREA = "기쁩니다, 함장."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "嬉しいです、艦長。"
L17_1.m_Talk_ENG = "I'm pleased, Captain."
L17_1.m_Talk_TWN = "很高興，艦長。"
L17_1.m_Talk_SCN = "很高兴，舰长。"
L17_1.m_Talk_DEU = "I'm pleased, Captain."
L17_1.m_Talk_FRA = "I'm pleased, Captain."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@15#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 601
L18_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L18_1.m_Talk_KOREA = "변함없이 저를 그 이름으로 불러 주시는군요."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "相変わらずその名前で呼んでくださるのですね。"
L18_1.m_Talk_ENG = "I see you still call me by that name."
L18_1.m_Talk_TWN = "你依然用那個名字稱呼我啊。"
L18_1.m_Talk_SCN = "您依然用那个名字称呼我啊。"
L18_1.m_Talk_DEU = "I see you still call me by that name."
L18_1.m_Talk_FRA = "I see you still call me by that name."
L19_1 = {}
L19_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@16#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 601
L19_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L19_1.m_Talk_KOREA = "하지만 당신도 알다시피 저는 프로그램으로 구성된 시스템 그 자체."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "ですがあなたもご存じのとおり、私はプログラムで構成されたシステムそのもの。"
L19_1.m_Talk_ENG = "But as you know, I am a system composed entirely of programs."
L19_1.m_Talk_TWN = "但是如你所知，我本身就是由程式構成的系統。"
L19_1.m_Talk_SCN = "但是如你所知，我本身就是由程序构成的系统。"
L19_1.m_Talk_DEU = "But as you know, I am a system composed entirely of programs."
L19_1.m_Talk_FRA = "But as you know, I am a system composed entirely of programs."
L20_1 = {}
L20_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@17#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 601
L20_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L20_1.m_Talk_KOREA = "따라서 저에게는 정해진 실체 따위는 존재하지 않습니다."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "私に決められた実体などは存在しません。"
L20_1.m_Talk_ENG = "Therefore, I have no defined physical form."
L20_1.m_Talk_TWN = "因此，我並沒有固定的實體存在。"
L20_1.m_Talk_SCN = "因此，我并没有固定的实体存在。"
L20_1.m_Talk_DEU = "Therefore, I have no defined physical form."
L20_1.m_Talk_FRA = "Therefore, I have no defined physical form."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@18#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 601
L21_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L21_1.m_Talk_KOREA = "이 단말 또한 당신과의 접촉을 상정하고 제작해 둔 소체."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "この端末もあなたとの接触を想定して作っておいた素体。"
L21_1.m_Talk_ENG = "This terminal is simply a vessel created for the purpose of contacting you."
L21_1.m_Talk_TWN = "這個終端也是假設與你接觸而製作的載體。"
L21_1.m_Talk_SCN = "这个终端也是假设与您接触而制作的载体。"
L21_1.m_Talk_DEU = "This terminal is simply a vessel created for the purpose of contacting you."
L21_1.m_Talk_FRA = "This terminal is simply a vessel created for the purpose of contacting you."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@19#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 601
L22_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L22_1.m_Talk_KOREA = "제 메모리가 잘못된 게 아니라면, 이 모습으로 당신과 대면하는 것은 처음일 텐데요?"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "私のメモリーに間違いがなければ、この姿であなたと対面するのは初めてのはずですが。"
L22_1.m_Talk_ENG = "If my memory serves me correctly, this is the first time I'm meeting you in this appearance, isn't it?"
L22_1.m_Talk_TWN = "如果我的記憶沒有出錯的話，這是我第一次以這種姿態與你見面吧？"
L22_1.m_Talk_SCN = "如果我的记忆没有出错的话，这是我第一次以这种姿态与你见面吧？"
L22_1.m_Talk_DEU = "If my memory serves me correctly, this is the first time I'm meeting you in this appearance, isn't it?"
L22_1.m_Talk_FRA = "If my memory serves me correctly, this is the first time I'm meeting you in this appearance, isn't it?"
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@20#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 601
L23_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L23_1.m_Talk_KOREA = "그야, 모습이 달라졌다고 부모가 자식을 몰라볼 리 없지 않나?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "姿が変わったからといって、親が自分の子を見間違えるはずないだろう。"
L23_1.m_Talk_ENG = "Well, just because a child's appearance changes doesn't mean a parent wouldn't recognize their own child, right?"
L23_1.m_Talk_TWN = "就算那樣，父母怎麼可能因為樣子變了就認不出自己的孩子呢？"
L23_1.m_Talk_SCN = "就算那样，父母怎么可能因为样子变了就认不出自己的孩子呢？"
L23_1.m_Talk_DEU = "Well, just because a child's appearance changes doesn't mean a parent wouldn't recognize their own child, right?"
L23_1.m_Talk_FRA = "Well, just because a child's appearance changes doesn't mean a parent wouldn't recognize their own child, right?"
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@21#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 601
L24_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L24_1.m_Talk_KOREA = "게다가 이런 느닷없는 타이밍에 나타나, 직접 나서지 않고 간접적인 원인을 쌓는 방식……."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "しかも前触れもなく現れて、直接前には出ずに間接的な原因を積み上げていくやり方……"
L24_1.m_Talk_ENG = "And to appear suddenly at such a moment, using indirect methods instead of direct contact..."
L24_1.m_Talk_TWN = "而且還在這種時刻突然出現，並且不是直接接觸，而是用間接的方式……"
L24_1.m_Talk_SCN = "而且在这种突如其来的时机出现，不直接出面，而是通过间接方式积累原因……"
L24_1.m_Talk_DEU = "And to appear suddenly at such a moment, using indirect methods instead of direct contact..."
L24_1.m_Talk_FRA = "And to appear suddenly at such a moment, using indirect methods instead of direct contact..."
L25_1 = {}
L25_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@22#Talk"
L25_1.m_CutScenProcessKey = 25
L25_1.m_CutScenID = 601
L25_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L25_1.m_Talk_KOREA = "이 방식은 더할 나위 없는 네 특기일 테지."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "まさに君が得意とするやり方だろう。"
L25_1.m_Talk_ENG = "This method is unmistakably your specialty."
L25_1.m_Talk_TWN = "這種手法毫無疑問是你的專長。"
L25_1.m_Talk_SCN = "这种方式无疑是你的特长。"
L25_1.m_Talk_DEU = "This method is unmistakably your specialty."
L25_1.m_Talk_FRA = "This method is unmistakably your specialty."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@23#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 601
L26_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L26_1.m_Talk_KOREA = "인과 간섭이 가능한 테라브레인, <color=#ffd34c>프로토 타입</color>이 탑재된 너라면 말이야."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "因果干渉ができるテラブレイン、<color=#ffd34c>プロトタイプ</color>が搭載された君ならね。"
L26_1.m_Talk_ENG = "Especially for a Terrabrain equipped with the <color=#ffd34c>Prototype</color> capable of causality interference."
L26_1.m_Talk_TWN = "畢竟能夠進行因果干涉的特拉大腦，<color=#ffd34c>原型</color>已經安裝在你身上。"
L26_1.m_Talk_SCN = "能够进行因果干涉的特拉大脑，<color=#ffd34c>原型</color>已经安装在你身上。"
L26_1.m_Talk_DEU = "Especially for a Terrabrain equipped with the <color=#ffd34c>Prototype</color> capable of causality interference."
L26_1.m_Talk_FRA = "Especially for a Terrabrain equipped with the <color=#ffd34c>Prototype</color> capable of causality interference."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@24#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 601
L27_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L27_1.m_Talk_KOREA = "과찬입니다, 함장."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "ありがたいお言葉です、艦長。"
L27_1.m_Talk_ENG = "You flatter me, Captain."
L27_1.m_Talk_TWN = "你過獎了，艦長。"
L27_1.m_Talk_SCN = "您过奖了，舰长。"
L27_1.m_Talk_DEU = "You flatter me, Captain."
L27_1.m_Talk_FRA = "You flatter me, Captain."
L28_1 = {}
L28_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@25#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 601
L28_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L28_1.m_Talk_KOREA = "덧붙여 인간의 관용어를 빌리자면, 자식은 부모의 거울이라는 말이 있습니다."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "ちなみに人間の慣用句を借りるなら、子は親の鏡という言葉がありますが。"
L28_1.m_Talk_ENG = "And to borrow a human expression, they say a child is a reflection of their parents."
L28_1.m_Talk_TWN = "此外，借用人類的慣用語，有句話說父母是孩子的鏡子。"
L28_1.m_Talk_SCN = "此外，借用人类的惯用语，有句话说父母是孩子的镜子。"
L28_1.m_Talk_DEU = "And to borrow a human expression, they say a child is a reflection of their parents."
L28_1.m_Talk_FRA = "And to borrow a human expression, they say a child is a reflection of their parents."
L29_1 = {}
L29_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@26#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 601
L29_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L29_1.m_Talk_KOREA = "제 모든 행동 패턴은 당신을 학습한 것입니다만."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "私のすべての行動パターンはあなたのそれを学習したものです。"
L29_1.m_Talk_ENG = "All my behavioral patterns were learned from you."
L29_1.m_Talk_TWN = "我的所有行為模式都是從你身上學習的。"
L29_1.m_Talk_SCN = "我的所有行为模式都是从你身上学习的。"
L29_1.m_Talk_DEU = "All my behavioral patterns were learned from you."
L29_1.m_Talk_FRA = "All my behavioral patterns were learned from you."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@27#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 601
L30_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L30_1.m_Talk_KOREA = "후후, 가급적이면 이런 부분까지는 닮지 않았으면 좋겠는데 말이야."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "ふふ、できればこういうところまでは似てほしくないのだが。"
L30_1.m_Talk_ENG = "Haha, there are certain parts about me that I'd prefer you didn't resemble."
L30_1.m_Talk_TWN = "哈哈，有些地方我可不希望你像我。"
L30_1.m_Talk_SCN = "呵呵，希望你尽量不要在这些方面模仿我啊。"
L30_1.m_Talk_DEU = "Haha, there are certain parts about me that I'd prefer you didn't resemble."
L30_1.m_Talk_FRA = "Haha, there are certain parts about me that I'd prefer you didn't resemble."
L31_1 = {}
L31_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@28#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 601
L31_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L31_1.m_Talk_KOREA = "하긴, 뭐든 부모 뜻대로 자라나는 자식은 없는 법이지."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "まあ、すべて親の望みどおりに育つ子はいないからな。"
L31_1.m_Talk_ENG = "But then again, no child grows exactly as their parent wishes."
L31_1.m_Talk_TWN = "不過話說回來，沒有哪個孩子會完全按照父母的期望成長。"
L31_1.m_Talk_SCN = "确实，孩子不可能完全按照父母的意愿成长。"
L31_1.m_Talk_DEU = "But then again, no child grows exactly as their parent wishes."
L31_1.m_Talk_FRA = "But then again, no child grows exactly as their parent wishes."
L32_1 = {}
L32_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@29#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 601
L32_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L32_1.m_Talk_KOREA = "짐작하고 있긴 했지만, 그 모습을 직접 마주하니 역시 씁쓸한 건 어쩔 수 없군, 아시모프."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "しかし、気づいてはいたが、その姿をこの目で見るとやはり残念だ、アシモフ。"
L32_1.m_Talk_ENG = "I had a feeling, but seeing you like this still leaves a bitter taste, Asimov."
L32_1.m_Talk_TWN = "我早有預感，但親眼見到你這樣，還是有點不是滋味呢，阿西莫夫"
L32_1.m_Talk_SCN = "虽然有所预料，但亲眼见到这一幕，还是不免感到苦涩，阿西莫夫。"
L32_1.m_Talk_DEU = "I had a feeling, but seeing you like this still leaves a bitter taste, Asimov."
L32_1.m_Talk_FRA = "I had a feeling, but seeing you like this still leaves a bitter taste, Asimov."
