L33_1.m_Talk_JPN = "……艦長。"
L33_1.m_Talk_ENG = "...Captain."
L33_1.m_Talk_TWN = "……艦長。"
L33_1.m_Talk_SCN = "……舰长。"
L33_1.m_Talk_DEU = "...Captain."
L33_1.m_Talk_FRA = "...Captain."
L34_1 = {}
L34_1.m_CutScenKey_Talk = "EP13_ACT3_INTERLUDE1@31#Talk"
L34_1.m_CutScenProcessKey = 34
L34_1.m_CutScenID = 601
L34_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L35_1 = "당신이 여전히 저를 자식처럼 여겨 주시는 건 영광입니다만."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "あなたが変わらず私のことを自分の子のように思ってくださるのは大変光栄ですが。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I'm honored that you still consider me your child."
L34_1.m_Talk_ENG = L35_1
L35_1 = "你仍然視我如子女，我感到非常榮幸。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "您仍然视我如子女，我感到非常荣幸。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "I'm honored that you still consider me your child."
L34_1.m_Talk_DEU = L35_1
L35_1 = "I'm honored that you still consider me your child."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP13_ACT3_INTERLUDE1@32#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 35
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 601
L35_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L36_1 = "지금의 저는 어디까지나 클리파의 위계를 이어받은 기계 장치의 마왕."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "今の私はあくまでもクリファの位階を受け継いだ機械装置の魔王。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "However, the current me is nothing more than a Demon Lord of Machinery who has inherited the Qlipha hierarchy."
L35_1.m_Talk_ENG = L36_1
L36_1 = "現在的我不過是繼承了逆卡巴拉級別的機械裝置魔王。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "现在的我不过是继承了逆卡巴拉阶级的机械装置之魔王。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "However, the current me is nothing more than a Demon Lord of Machinery who has inherited the Qlipha hierarchy."
L35_1.m_Talk_DEU = L36_1
L36_1 = "However, the current me is nothing more than a Demon Lord of Machinery who has inherited the Qlipha hierarchy."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP13_ACT3_INTERLUDE1@33#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 36
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 601
L36_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L37_1 = "제게 주어진 기동 목적에 따라, 이 세계가 마땅히 치러야 할 시험을 내리는 존재이자."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "定められた起動目的に従い、この世界が乗り越えるべき試験を与える存在であり。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "In line with my designated purpose, I am the one who administers the trials this world must undergo."
L36_1.m_Talk_ENG = L37_1
L37_1 = "根據我被賦予的行動目的，我是施予這個世界應當接受的試煉的施予者。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "根据我被赋予的行动目的，我是施予这个世界应当接受的试炼的施予者。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "In line with my designated purpose, I am the one who administers the trials this world must undergo."
L36_1.m_Talk_DEU = L37_1
L37_1 = "In line with my designated purpose, I am the one who administers the trials this world must undergo."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP13_ACT3_INTERLUDE1@34#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 37
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 601
L37_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L38_1 = "동시에 필연적 멸망으로부터 인류를 낙원으로 이끌 구원의 방주입니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "同時に必然的滅亡から人類を楽園へ導く救世の箱舟なのです。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "At the same time, I am the Ark of salvation that will guide humanity to paradise from inevitable destruction."
L37_1.m_Talk_ENG = L38_1
L38_1 = "同時也是將人類從必然的毀滅中，引導至樂園的救贖方舟。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "同时也是将人类从必然的毁灭中引导至乐园的救赎方舟。"
L37_1.m_Talk_SCN = L38_1
