L44_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L45_1 = "당신이 우주로 쏘아 올린 검은 짐승은 제가 내려보낸 사도를 요격하는 데 성공했죠."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "あなたが宇宙に打ち上げた黒い獣は、私が送った使徒を見事に迎撃しました。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "The black beast you launched into space successfully intercepted the Apostle I sent down."
L44_1.m_Talk_ENG = L45_1
L45_1 = "你射向宇宙的黑色野獸成功攔截了我派出的使徒。"
