L45_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L46_1 = "함장, 당신도 알다시피 그것은 예정된 인과로부터 벗어난 일."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "艦長、あなたもご存じでしょうが、それは予定された因果から外れたこと。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Captain, as you know, that event deviated from the predetermined causality."
L45_1.m_Talk_ENG = L46_1
L46_1 = "艦長，正如你所知，那是脫離預定因果的事。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "舰长，正如你所知，那是脱离预定因果的事。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Captain, as you know, that event deviated from the predetermined causality."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Captain, as you know, that event deviated from the predetermined causality."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EP13_ACT3_INTERLUDE1@41#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 601
L46_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
