L46_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L47_1 = "그러나 당신이 그동안 수없이 쌓아 올린 충분한 원인은 인과율에 변수를 발생시켰고."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ですが、あなたが今まで幾重にも積み上げてきた十分な原因は、因果律に変数を発生させ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "However, the countless variables you have accumulated over the years created a ripple in causality."
L46_1.m_Talk_ENG = L47_1
L47_1 = "然而，你在這段時間裡無數次積累的充分原因，已經在因果律中產生了變數。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "然而，你在这段时间里无数次积累的充分原因已经在因果律中产生了变量。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "However, the countless variables you have accumulated over the years created a ripple in causality."
L46_1.m_Talk_DEU = L47_1
L47_1 = "However, the countless variables you have accumulated over the years created a ripple in causality."
