L2_1 = "원래라면 클리포트 게임에서 패배한 당신은 다음 세계로의 철수를 선택했겠지만……."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "本来ならクリフォトゲームで敗北したあなたは、次の世界に撤収することを選んだはずですが……"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Normally, after losing the Qliphoth Game, you would have chosen to withdraw to the next world…"
L1_1.m_Talk_ENG = L2_1
L2_1 = "原本在逆卡巴拉遊戲中失敗的你會選擇撤退到下一個世界……"
L1_1.m_Talk_TWN = L2_1
L2_1 = "原本在神圣战役中失败的你会选择撤退到下一个世界……"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Normally, after losing the Qliphoth Game, you would have chosen to withdraw to the next world…"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Normally, after losing the Qliphoth Game, you would have chosen to withdraw to the next world…"
L1_1.m_Talk_FRA = L2_1
