L3_1 = "EP13_ACT3_INTERLUDE1@45#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 601
L2_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L3_1 = "그 변수는 결국 어린 늑대가 탐미엘에게 상처를 입히는 이변을 낳았죠."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "その変数は、ついには幼いオオカミがタミエルに傷を負わせるという異変を生んだ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "But that variable ultimately led to a disturbance where the young Wolf wounded Tammiel."
L2_1.m_Talk_ENG = L3_1
L3_1 = "那個變數最終導致幼狼給塔米爾造成傷害的異變。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "那个变数最终导致小狼给塔米尔造成了伤害的异变。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "But that variable ultimately led to a disturbance where the young Wolf wounded Tammiel."
L2_1.m_Talk_DEU = L3_1
L3_1 = "But that variable ultimately led to a disturbance where the young Wolf wounded Tammiel."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP13_ACT3_INTERLUDE1@46#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 601
L3_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L4_1 = "믿을 수 없는 현실 개변을 목격한 순간. 당신은 즉시 시공간 종료 프로토콜을 변경."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "目を疑うような現実改変を目撃した瞬間。あなたは直ちに時空間終了プロトコルを変更。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "At the moment you witnessed that unbelievable change in reality, you immediately altered the spacetime abortion protocol."
L3_1.m_Talk_ENG = L4_1
L4_1 = "目睹了難以置信的現實變革瞬間。你立即更改時空終止協議。"
L3_1.m_Talk_TWN = L4_1
