L9_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L10_1 = "여러 세계를 거치며, 당신이 준비해 왔던 안배들이 한곳에 모여 맞물리기 시작했고."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "数々の世界を経て、あなたが打ってきた布石が一つの点で重なり合い始め。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "As you traveled through the worlds, the contingencies you had been preparing began to converge and interlock."
L9_1.m_Talk_ENG = L10_1
L10_1 = "穿越多個世界，你一直準備的各種應變措施開始逐漸匯聚，並相互銜接起來。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "穿越多个世界，你所准备的安排开始汇聚并相互作用。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "As you traveled through the worlds, the contingencies you had been preparing began to converge and interlock."
