L12_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L13_1 = "그 작고, 미약했던 날갯짓이 모이고, 또 모여서……."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "その小さく、微弱だった羽ばたきが次第に集まって……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "The small, insignificant flutters gathered and accumulated..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "那些微不足道的細微波動逐漸匯聚、積累……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "那微弱的翅膀拍动，渐渐聚集起来……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "The small, insignificant flutters gathered and accumulated..."
L12_1.m_Talk_DEU = L13_1
L13_1 = "The small, insignificant flutters gathered and accumulated..."
L12_1.m_Talk_FRA = L13_1
