L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 601
L13_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L14_1 = "최종적으로 세계는 클리포트 게임이라는 거대한 풍랑에 맞설 수 있었으니까요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "最終的に世界はクリフォトゲームという巨大な嵐に立ち向かうことができたのですから。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Eventually allowing this world to withstand the storm known as the Qliphoth Game."
L13_1.m_Talk_ENG = L14_1
L14_1 = "最終，讓這個世界得以承受逆卡巴拉遊戲的風暴。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "最终世界能够抵御神圣战役这个巨大的风暴。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Eventually allowing this world to withstand the storm known as the Qliphoth Game."
L13_1.m_Talk_DEU = L14_1
