L16_1 = "EP13_ACT3_INTERLUDE1@54#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 601
L15_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L16_1 = "저와 당신… 그리고 기술의 정점을 이뤘던 연합조차 다다를 수 없었던 지점이죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私とあなた……そして技術の頂点にあった連合すらもたどり着けなかった地点です。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "A point that neither you, nor I... nor even the Alliance that once reached the peak of technology could have ever reached."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我和你……以及曾達到技術巔峰的聯盟都無法觸及的地方。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "我和你……以及曾达到技术巅峰的联盟都无法触及的地方。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "A point that neither you, nor I... nor even the Alliance that once reached the peak of technology could have ever reached."
