L20_1 = "EP13_ACT3_INTERLUDE1@56#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 69
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 601
L19_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L20_1 = "하지만 클리포트 게임의 승리가 오로지 내 선택에 의해 정해졌다는 건, 오만일 뿐이야."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "クリフォトゲームの勝利が私の選択によって決定づけられたというのは、傲慢すぎるな。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "But claiming that the victory in the Qliphoth Game was solely due to my choices would be pure arrogance."
L19_1.m_Talk_ENG = L20_1
L20_1 = "但認為逆卡巴拉遊戲的勝利僅僅取決於我的選擇，那就太傲慢了。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "但认为神圣战役的胜利仅仅取决于我的选择，那不过是傲慢罢了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "But claiming that the victory in the Qliphoth Game was solely due to my choices would be pure arrogance."
L19_1.m_Talk_DEU = L20_1
L20_1 = "But claiming that the victory in the Qliphoth Game was solely due to my choices would be pure arrogance."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP13_ACT3_INTERLUDE1@57#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 70
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 601
L20_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L21_1 = "시공을 초월하여, 모든 이들의 의지와 선택이 있었기에 끝내 다다를 수 있었지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "時空を超越し、すべての者たちの意志と選択があってこそやっとたどり着けたんだ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Transcending time and space, the wills and choices of many were what led to that final outcome."
L20_1.m_Talk_ENG = L21_1
L21_1 = "超越時空，正因為有所有人的意志和選擇，最終才能到達。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "超越时空，正因为有所有人的意志和选择，最终才能到达。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Transcending time and space, the wills and choices of many were what led to that final outcome."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Transcending time and space, the wills and choices of many were what led to that final outcome."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP13_ACT3_INTERLUDE1@58#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 71
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 601
L21_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L21_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L22_1 = "여전히 겸손하시군요, 함장."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "謙虚なところもそのままですね、艦長。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You remain as humble as ever, Captain."
L21_1.m_Talk_ENG = L22_1
L22_1 = "你依然很謙虛，艦長。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "您依然很谦虚，舰长。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "You remain as humble as ever, Captain."
L21_1.m_Talk_DEU = L22_1
L22_1 = "You remain as humble as ever, Captain."
