L23_1 = "EP13_ACT3_INTERLUDE1@59#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 72
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 601
L22_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L23_1 = "설령, 기적이라 할지라도 일어날 일은 반드시 일어나기 마련입니다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "たとえそれが奇跡だろうと、起こるべきことは必ず起こるものです。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Even if it is a miracle, what is meant to happen is bound to happen."
L22_1.m_Talk_ENG = L23_1
L23_1 = "即使是奇蹟，也必然會發生。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "即使是奇迹，也必然会发生。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Even if it is a miracle, what is meant to happen is bound to happen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Even if it is a miracle, what is meant to happen is bound to happen."
L22_1.m_Talk_FRA = L23_1
