L24_1 = "EP13_ACT3_INTERLUDE1@60#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 601
L23_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L24_1 = "애초에 관측자로서 당신이 존재하지 않았다면, 이 세계에 변수 따위 발생하지 않았겠죠."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そもそも観測者としてのあなたがいなかったら、この世界に変数など発生しなかったはずです。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "If you had not existed as the observer, there would have been no variables in this world."
L23_1.m_Talk_ENG = L24_1
L24_1 = "如果作為觀察者的你根本不存在，那麼這個世界就不會出現任何變數了吧。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "如果作为观察者的你根本不存在，那么这个世界就不会出现任何变量了吧。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "If you had not existed as the observer, there would have been no variables in this world."
L23_1.m_Talk_DEU = L24_1
L24_1 = "If you had not existed as the observer, there would have been no variables in this world."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP13_ACT3_INTERLUDE1@61#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 74
L24_1.m_CutScenProcessKey = L25_1
