L24_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L25_1 = "탐미엘이 세피로트 나무를 장악하고 있는 이상, 세계의 멸망은 필연적이니까요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "タミエルがセフィロトを掌握している以上、世界の滅亡は必然なのですから。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "As long as Tammiel continues to control the Tree of Sephiroth, the world's destruction is inevitable."
L24_1.m_Talk_ENG = L25_1
L25_1 = "既然塔米爾掌控了生命樹，世界的毀滅就是必然的了。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "既然塔米尔掌控了塞菲罗特之树，世界的毁灭就是必然的了。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "As long as Tammiel continues to control the Tree of Sephiroth, the world's destruction is inevitable."
L24_1.m_Talk_DEU = L25_1
L25_1 = "As long as Tammiel continues to control the Tree of Sephiroth, the world's destruction is inevitable."
