L27_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L28_1 = "역시 클리포트 게임 직후에 발생한 현실 개변은 세피로트 나무에 의한 현상인가?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "やはりクリフォトゲーム直後に発生した現実改変はセフィロトによる現象だったのか？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "So the change in reality that occurred after the Qliphoth Game was caused by the Tree of Sephiroth?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "果然，逆卡巴拉遊戲之後發生的現實變更是由於生命樹嗎？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "果然，神圣战役之后发生的现实变更是由于塞菲罗特之树吗？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "So the change in reality that occurred after the Qliphoth Game was caused by the Tree of Sephiroth?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "So the change in reality that occurred after the Qliphoth Game was caused by the Tree of Sephiroth?"
L27_1.m_Talk_FRA = L28_1
