L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L29_1 = "그렇다면, 네 목적은 여전히 세피로트 나무가 있는 장소에 다다르는 것이겠지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "だとしたら、セフィロトにたどり着くという君の目標は、今でも変わらないのだな。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Then, your objective must still be to reach the place where the Tree of Sephiroth is located."
L28_1.m_Talk_ENG = L29_1
L29_1 = "那麼，你的目的仍然是到達有生命樹的地方吧。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "那么，你的目的仍然是到达有塞菲罗特之树的地方吧。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Then, your objective must still be to reach the place where the Tree of Sephiroth is located."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Then, your objective must still be to reach the place where the Tree of Sephiroth is located."
L28_1.m_Talk_FRA = L29_1
