L30_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L31_1 = "당신도 알다시피, 저는 성간 관리 연합의 총괄 네비게이션 시스템."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "あなたもご存じのとおり、私は星間管理連合の総括ナビゲーションシステム。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "As you know, I am the Interstellar Administration Alliance Central Navigation System."
L30_1.m_Talk_ENG = L31_1
L31_1 = "如你所知，我是星際管理聯盟的總導航系統。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "如你所知，我是星际管理联盟的总导航系统。"
