L31_1 = "As you know, I am the Interstellar Administration Alliance Central Navigation System."
L30_1.m_Talk_DEU = L31_1
L31_1 = "As you know, I am the Interstellar Administration Alliance Central Navigation System."
L30_1.m_Talk_FRA = L31_1
