L31_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L32_1 = "방주로서 제 기동 목적은 인류를 선별하고, 선별된 인류를 낙원으로 인도하는 것입니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "箱舟としての私の起動目的は、人類を選別し、選ばれた人類を楽園に導くことです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "As the Ark, my objective is to select humanity and guide the chosen ones to paradise."
L31_1.m_Talk_ENG = L32_1
L32_1 = "作為方舟，我啟動目的就是篩選人類，並將被篩選的人類引導至樂園。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "作为方舟，我的启动目的就是筛选人类，并将被筛选的人类引导至乐园。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "As the Ark, my objective is to select humanity and guide the chosen ones to paradise."
L31_1.m_Talk_DEU = L32_1
L32_1 = "As the Ark, my objective is to select humanity and guide the chosen ones to paradise."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
