L32_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L33_1 = "따라서 저는 이 땅에 내려온 세피로트 나무의 파편을 관측해야 할 의무가 있죠."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ですので私にはこの地に降臨したセフィロトの破片を観測する義務があります。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Therefore, I am obligated to observe the Tree of Sephiroth's fragment that has descended to this land."
L32_1.m_Talk_ENG = L33_1
L33_1 = "因此，我有義務觀察降臨此地的生命樹碎片。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "因此，我有义务观察降临此地的塞菲罗特之树碎片。"
