L5_1 = "EP13_ACT3_INTERLUDE1@81#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 601
L4_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L5_1 = "만약 스완이 세피로트 나무의 파편을 확보했다면, 그 말은 단순한 허세가 아니게 되겠군."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "もしスワンがセフィロトの破片を手に入れていたとしたら、その言葉は単なる虚勢ではないわけだ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "If Swan has secured a fragment of the Tree of Sephiroth, then those words are more than just a bluff."
L4_1.m_Talk_ENG = L5_1
L5_1 = "如果史旺已經獲得了生命樹的碎片，那麼這句話就不再只是虛張聲勢了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "如果斯旺已经获得了塞菲罗特之树的碎片，那么这句话就不再只是虚张声势了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "If Swan has secured a fragment of the Tree of Sephiroth, then those words are more than just a bluff."
L4_1.m_Talk_DEU = L5_1
L5_1 = "If Swan has secured a fragment of the Tree of Sephiroth, then those words are more than just a bluff."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
