L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 601
L5_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
