L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L6_1 = "하지만 이건 너답지 않은 방식이야, 아시모프."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "しかしこれは君らしくないな、アシモフ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But this doesn't suit you, Asimov."
L5_1.m_Talk_ENG = L6_1
L6_1 = "但是這不是你的風格，阿西莫夫。"
L5_1.m_Talk_TWN = L6_1
