L7_1 = "EP13_ACT3_INTERLUDE1@83#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 601
L6_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L7_1 = "세피로트 나무가 있는 장소에 다다를 단서를 앞에 두고, 너는 뭘 망설이고 있는 거지?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "セフィロトがある場所にたどり着く手がかりを前にして、何をためらっているんだ？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Why are you holding back when you have the clue that will lead you to the Tree of Sephiroth's location?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "在你面前有通往生命樹所在地點的線索，你還在猶豫什麼？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "在你面前有通往塞菲罗特之树所在地点的线索，你还在犹豫什么？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Why are you holding back when you have the clue that will lead you to the Tree of Sephiroth's location?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Why are you holding back when you have the clue that will lead you to the Tree of Sephiroth's location?"
L6_1.m_Talk_FRA = L7_1
