L8_1 = "EP13_ACT3_INTERLUDE1@84#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 601
L7_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L8_1 = "달의 뒷면에서 줄곧 때를 기다려왔던 네가 어째서 이번에는 직접 모습을 드러낸 건가?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "月の裏側でずっと時を待っていた君が、どうして今回は直接姿を現したのかね？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "What made you reveal yourself when you've been patiently waiting for the right time on the dark side of the moon?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "你一直在月球背面等待時機，這次為什麼？自現身了？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "你一直在月球背面等待时机，这次为什么亲自现身了？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "What made you reveal yourself when you've been patiently waiting for the right time on the dark side of the moon?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "What made you reveal yourself when you've been patiently waiting for the right time on the dark side of the moon?"
L7_1.m_Talk_FRA = L8_1
