L11_1 = "EP13_ACT3_INTERLUDE1@86#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 110
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 601
L10_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_StartFXSoundName = "FX_CUTSCEN_BEEP"
L10_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L11_1 = "함장, 당신은 여전히 얕잡아 볼 수 없는 상대로군요."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "艦長、あなたは相変わらず侮れない相手ですね。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Captain, you remain a formidable opponent."
L10_1.m_Talk_ENG = L11_1
L11_1 = "艦長，你依然是個不可小覷的對手啊。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "舰长，你依然是个不可小觑的对手啊。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Captain, you remain a formidable opponent."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Captain, you remain a formidable opponent."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP13_ACT3_INTERLUDE1@87#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 111
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 601
L11_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L12_1 = "변수의 간섭 때문에 입을 열 수 없다면, 적어도 분기의 조건을 명확히 하도록 해."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "変数による干渉を理由に教えられないというのなら、少なくとも分岐の条件は明確にしたまえ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "If you can't speak openly due to variable interference, then at least clarify the branching point conditions."
L11_1.m_Talk_ENG = L12_1
L12_1 = "如果因為變數干擾而無法明說，那至少把分歧點的條件說清楚。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "如果因为变量的干扰而无法开口，那么至少要明确季度的条件。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "If you can't speak openly due to variable interference, then at least clarify the branching point conditions."
L11_1.m_Talk_DEU = L12_1
L12_1 = "If you can't speak openly due to variable interference, then at least clarify the branching point conditions."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP13_ACT3_INTERLUDE1@88#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 601
L12_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L13_1 = "네가 내세우는 시험이란, 스완의 계획을 저지하는 일인가?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "君が主張する試験とは、スワンの計画を阻止することか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "This trial, is it to stop Swan's plan?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "你所提出的考驗，是阻止史旺的計畫嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "你所提出的考验，是阻止斯旺的计划吗？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "This trial, is it to stop Swan's plan?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "This trial, is it to stop Swan's plan?"
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP13_ACT3_INTERLUDE1@89#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 113
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 601
L13_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "USER_ADMIN_NULL_NULL"
L14_1 = "그게 아니라면, 세피로트 나무의 파편을 회수하는 것인가?"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それとも、セフィロトの破片を回収することか？"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Or is it about retrieving the Tree of Sephiroth's fragment?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "如果不是這樣，那就是要回收生命樹的碎片嗎？"
L13_1.m_Talk_TWN = L14_1
L14_1 = "如果不是这样，那就是要回收塞菲罗特之树的碎片吗？"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Or is it about retrieving the Tree of Sephiroth's fragment?"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Or is it about retrieving the Tree of Sephiroth's fragment?"
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP13_ACT3_INTERLUDE1@90#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 601
L14_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L15_1 = "둘 다 오답입니다, 함장."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "両方ともハズレです、艦長。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Neither, Captain."
L14_1.m_Talk_ENG = L15_1
L15_1 = "兩個都是錯誤答案，艦長。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "两个都是错误答案，舰长。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Neither, Captain."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Neither, Captain."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP13_ACT3_INTERLUDE1@91#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 601
L15_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L16_1 = "저는 엄정한 기계 장치의 마왕. 현시점에서 누구의 편도 아니죠."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私は厳正なる機械装置の魔王。現時点では誰の味方でもありません。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I am a strict Demon Lord of Machinery. At this point, I am on no one's side."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我是嚴謹的機械裝置魔王。目前不屬於任何一方。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "我是严谨的机械装置之魔王。目前不属于任何一方。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "I am a strict Demon Lord of Machinery. At this point, I am on no one's side."
L15_1.m_Talk_DEU = L16_1
L16_1 = "I am a strict Demon Lord of Machinery. At this point, I am on no one's side."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP13_ACT3_INTERLUDE1@92#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 601
L16_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L17_1 = "경우에 따라서는 그 엑자일러의 계획에 협력하는 것 또한 고려 대상 중 하나입니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "場合によっては、あのエグザイラーの計画に協力する選択肢もありえます。"
L16_1.m_Talk_JPN = L17_1
