L30_1 = "어쩌면 스완이 있는 장소는 고심도 이면세계의 어딘가일지도 모르겠군."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "もしかしたらスワンがいる場所は高深度裏世界のどこかなのかもしれないな。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Swan's location might just be somewhere in the hyperdepths of Counterside."
L29_1.m_Talk_ENG = L30_1
L30_1 = "或許史旺所在的地方是高深度異界的某個地方吧。"
L29_1.m_Talk_TWN = L30_1
