L31_1 = "하지만 그렇다고 하더라도 현시점에서 저희의 힘만으로는 대처할 시간이 부족하군요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "そうだとしても現時点で私たちの力だけでは対処する時間が足りません。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Even so, we don't have enough time to handle this with just our current resources."
L30_1.m_Talk_ENG = L31_1
L31_1 = "但是即便如此，目前單憑我們的力量還是沒有足夠的時間來應對。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "但是即便如此，目前仅凭我们的力量还是没有足够的时间来应对。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Even so, we don't have enough time to handle this with just our current resources."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Even so, we don't have enough time to handle this with just our current resources."
L30_1.m_Talk_FRA = L31_1
