L32_1 = "목적지가 이면세계라면 타이밍이 좋지 않아요. 당장은 코핀 함도 압류 당한 상황이니까요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "目的地が裏世界だというならタイミングが悪かったですね。今はコフィン艦も差し押さえられている状態ですから。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "If the destination is the Counterside, the timing is terrible. After all, the Coffin is under seizure."
L31_1.m_Talk_ENG = L32_1
L32_1 = "如果目的地是異界，那時機不太好。因為目前科芬艦也被扣押中。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "如果目的地是异界，那时机不太好。因为目前科芬舰也被扣押了。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "If the destination is the Counterside, the timing is terrible. After all, the Coffin is under seizure."
L31_1.m_Talk_DEU = L32_1
L32_1 = "If the destination is the Counterside, the timing is terrible. After all, the Coffin is under seizure."
