L34_1 = "만약, 그 현상의 결과가 네 기준을 만족하지 못한다면, 그때는 어떻게 되지?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "もし、その現象の結果が君の基準を満たさなかったら、その時はどうなる？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "If the outcome of that phenomenon does not meet your criteria, what will happen then?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "如果那個現象的結果不符合你的標準，那會怎麼樣呢？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "如果那个现象的结果不符合你的标准，那会怎么样呢？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "If the outcome of that phenomenon does not meet your criteria, what will happen then?"
L33_1.m_Talk_DEU = L34_1
