L37_1 = "EP13_ACT3_INTERLUDE1@109#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 601
L36_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L37_1 = "제가 이 세계에 대해 선별 프로세스를 보류하고 있는 이유는 단 하나."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "私がこの世界の選別プロセスを保留している理由はたったひとつ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "There is only one reason why I have suspended the selection process for this world."
L36_1.m_Talk_ENG = L37_1
L37_1 = "我暫緩對這個世界進行篩選流程的原因只有一個。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "我暂缓对这个世界进行筛选流程的原因只有一个。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "There is only one reason why I have suspended the selection process for this world."
L36_1.m_Talk_DEU = L37_1
L37_1 = "There is only one reason why I have suspended the selection process for this world."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP13_ACT3_INTERLUDE1@110#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 601
L37_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L38_1 = "그것은 이 세계가 제가 연산한 인과로부터 벗어난 세계이기 때문입니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "それは私が演算した因果からこの世界が外れているからです。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "It's because this world deviated from the causality I calculated."
L37_1.m_Talk_ENG = L38_1
L38_1 = "因為這個世界是脫離我計算因果的世界。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "因为这个世界是脱离我计算因果的世界。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "It's because this world deviated from the causality I calculated."
L37_1.m_Talk_DEU = L38_1
L38_1 = "It's because this world deviated from the causality I calculated."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP13_ACT3_INTERLUDE1@111#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 601
L38_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L39_1 = "제가 관측한 어떤 세계도 <color=#ffd34c>끝</color>을 넘어선 세계는 없었으니까요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "私が観測を始めて以来、<color=#ffd34c>終わり</color>を乗り越えた世界はありませんでした。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "In all the worlds I observed, not one has surpassed the <color=#ffd34c>end</color>."
L38_1.m_Talk_ENG = L39_1
L39_1 = "因為我觀察過的任何世界都沒有超越<color=#ffd34c>終結</color>的世界。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "因为我观察过的任何世界都没有超越<color=#ffd34c>终结</color>的世界。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "In all the worlds I observed, not one has surpassed the <color=#ffd34c>end</color>."
L38_1.m_Talk_DEU = L39_1
L39_1 = "In all the worlds I observed, not one has surpassed the <color=#ffd34c>end</color>."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP13_ACT3_INTERLUDE1@112#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 601
L39_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L40_1 = "하지만 이번 분기점조차 결국에는 무의미한 멸망으로 수렴하게 된다면."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "ですが今回の分岐点すらも結局は無意味な滅亡に繋がるとしたら。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "However, if this turning point still converges into meaningless destruction..."
L39_1.m_Talk_ENG = L40_1
L40_1 = "但是如果這次分界點最終還是無意義的毀滅…"
L39_1.m_Talk_TWN = L40_1
L40_1 = "但是如果这次分界点最终还是归于无意义的毁灭。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "However, if this turning point still converges into meaningless destruction..."
L39_1.m_Talk_DEU = L40_1
L40_1 = "However, if this turning point still converges into meaningless destruction..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP13_ACT3_INTERLUDE1@113#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 601
L40_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L41_1 = "구태여 무가치한 실패를 반복할 이유가 없겠죠."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あえて価値のない失敗を繰り返す理由はありません。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Then there is no point in repeating a worthless failure."
L40_1.m_Talk_ENG = L41_1
L41_1 = "沒有必要重複毫無價值的失敗吧。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "没有必要重复毫无价值的失败吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Then there is no point in repeating a worthless failure."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Then there is no point in repeating a worthless failure."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP13_ACT3_INTERLUDE1@114#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 601
L41_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L42_1 = "따라서 지금까지 모든 히스토리를 아카이브. 인류를 대상으로 선별 프로세스를 수행."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "従って、今までのすべてのヒストリーをアーカイブ。人類を対象に選別プロセスを遂行。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Thus, I have archived all historical data up to this point and initiated the mankind selection process."
L41_1.m_Talk_ENG = L42_1
L42_1 = "因此，至今為止所有歷史都已歸檔。針對人類進行篩選流程。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "因此，至今为止所有历史都已归档。针对人类进行筛选流程。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Thus, I have archived all historical data up to this point and initiated the mankind selection process."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Thus, I have archived all historical data up to this point and initiated the mankind selection process."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP13_ACT3_INTERLUDE1@115#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 601
L42_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L43_1 = "선별된 인류를 보존 처리하여 이민선에 수납합니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "選別された人類を保存処理し、移民船に収納します。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "The selected humans will be preserved and stored within the Exodus Fleet."
L42_1.m_Talk_ENG = L43_1
L43_1 = "將精選的人類進行保存處理並收納到移民船中。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "将精选的人类进行保存处理并收纳到移民船中。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "The selected humans will be preserved and stored within the Exodus Fleet."
L42_1.m_Talk_DEU = L43_1
L43_1 = "The selected humans will be preserved and stored within the Exodus Fleet."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = "EP13_ACT3_INTERLUDE1@116#Talk"
L43_1.m_CutScenKey_Talk = L44_1
L44_1 = 143
L43_1.m_CutScenProcessKey = L44_1
L43_1.m_CutScenID = 601
L43_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L44_1 = "그 후, 코핀 오브 릴리스의 동력을 사용하여 프로토콜 CoW를 발동."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "その後、コフィン・オブ・リリスの動力を使用しプロトコルCoWを発動。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Afterward, the Coffin of Lilith will activate Protocol: CoW using its power source."
L43_1.m_Talk_ENG = L44_1
L44_1 = "之後，莉莉絲之科芬將會啟動CoW協議，並以其作為動力源。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "之后，利用科芬所属莉莉丝的动力启动CoW协议。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Afterward, the Coffin of Lilith will activate Protocol: CoW using its power source."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Afterward, the Coffin of Lilith will activate Protocol: CoW using its power source."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
