L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 601
L44_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L45_1 = "세계선을 이동하여 모든 변수를 초기화. 최초부터 낙원 탐사 플랜을 다시 시작합니다."
