L9_1 = "Therefore, Captain, I will select you and extract your brain."
L8_1.m_Talk_ENG = L9_1
L9_1 = "所以，艦長，我將選擇你，並提取你的大腦。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "因此，舰长，选择你来摘取大脑。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Therefore, Captain, I will select you and extract your brain."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Therefore, Captain, I will select you and extract your brain."
L8_1.m_Talk_FRA = L9_1
