L10_1 = "EP13_ACT3_INTERLUDE1@132#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 601
L9_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L10_1 = "적출한 두뇌를 테라브레인으로 해석하여 전자화. 전뇌 상태의 프로그램으로 치환합니다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "摘出した頭脳をテラブレインで解析し電子化。電脳状態のプログラムに置換します。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Your brain will be processed and digitized as a Terrabrain, converting it into a program."
L9_1.m_Talk_ENG = L10_1
L10_1 = "你的大腦將被處理並數位化成為特拉大腦，轉換成程式。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "将摘取的大脑解析为特拉大脑并电子化。替换为电子脑状态的程序。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Your brain will be processed and digitized as a Terrabrain, converting it into a program."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Your brain will be processed and digitized as a Terrabrain, converting it into a program."
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
L11_1 = "EP13_ACT3_INTERLUDE1@133#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 601
L10_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L11_1 = "그 뒤 최종 시퀸스를 통해, 제 인공지능과 함장의 두뇌를 동기화. 의식의 융합을 시도."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "その後最終シーケンスを通じ、私の人工知能と艦長の頭脳を同期化。意識の融合を開始。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "After that, I will synchronize your consciousness with my AI through the final sequence, attempting a fusion of our minds."
L10_1.m_Talk_ENG = L11_1
L11_1 = "之後，我將透過最終序列將你的頭腦與我的AI同步，嘗試融合我們的意識。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "之后通过最终程序，将我的人工智能与舰长的大脑同步。尝试意识的融合。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "After that, I will synchronize your consciousness with my AI through the final sequence, attempting a fusion of our minds."
L10_1.m_Talk_DEU = L11_1
L11_1 = "After that, I will synchronize your consciousness with my AI through the final sequence, attempting a fusion of our minds."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP13_ACT3_INTERLUDE1@134#Talk"
