L11_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L12_1 = "만약 그 시도가 성공한다면, 저는 함장이 되고 함장은 제가 되겠죠."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "もしそれが成功すれば、私は艦長となり、艦長は私となるでしょう。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "If the attempt succeeds, I will become you, and you will become me."
L11_1.m_Talk_ENG = L12_1
L12_1 = "如果那個嘗試成功的話，我就會成為艦長，而艦長就會成為我。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "如果那个尝试成功的话，我就会成为舰长，而舰长就会成为我。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "If the attempt succeeds, I will become you, and you will become me."
L11_1.m_Talk_DEU = L12_1
L12_1 = "If the attempt succeeds, I will become you, and you will become me."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
