L20_1 = "당황스럽지만… 아무래도 자네가 들은 그대로인 것 같군, 부사장."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "残念だが……どうやら君が聞いたとおりのようだね、副社長。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "It's alarming, but... yes, I believe you heard it right, Vice President."
L19_1.m_Talk_ENG = L20_1
L20_1 = "雖然有些驚訝……但看來你聽到的就是事實，副總。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "虽然有些惊讶……但看来你听到的就是事实，副总。"
