L20_1.m_fTalkTime = 0.03
L21_1 = "それにアシモフは嘘をつかない。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "And Asimov does not lie."
L20_1.m_Talk_ENG = L21_1
L21_1 = "而且阿西莫夫是不會說謊的。"
