L26_1 = "EP13_ACT3_INTERLUDE1@143#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 175
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 601
L25_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L26_1 = "당신과 작별한 뒤, 저는 오랜 시간 탐사를 이어오며, 오직 당신만을 생각해 왔습니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あなたと別れてから、私は長い間探査しながらあなただけを思ってきました。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Since we parted ways, I have been thinking only of you while exploring for eons."
L25_1.m_Talk_ENG = L26_1
L26_1 = "與你告別後，我在漫長的探索中一直只想著你。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "与您告别后，我在漫长的探索中一直只想着您。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Since we parted ways, I have been thinking only of you while exploring for eons."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Since we parted ways, I have been thinking only of you while exploring for eons."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP13_ACT3_INTERLUDE1@144#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 601
L26_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L27_1 = "메모리에 저장된 당신의 말을 되뇌며, 의도를 추정하기 위해 연산능력을 할애해 왔죠."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "メモリーに記録されたあなたの言葉を繰り返し、意図を推定するために演算能力を使いました。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I replayed your words stored in my memory, dedicating my processing power to decipher your intentions."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我一直在回憶存儲在記憶中的你的話，並分配計算能力來推測你的意圖。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "我一直在回忆存储在记忆中的你的话，并分配计算能力来推测你的意图。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "I replayed your words stored in my memory, dedicating my processing power to decipher your intentions."
L26_1.m_Talk_DEU = L27_1
L27_1 = "I replayed your words stored in my memory, dedicating my processing power to decipher your intentions."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP13_ACT3_INTERLUDE1@145#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 177
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 601
L27_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L28_1 = "줄곧 당신이라는 존재를 이해하기 위해 노력해왔습니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ずっとあなたという存在を理解しようと努力し続けてきました。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I have been striving to understand you."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我一直在努力理解你這個存在。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "我一直在努力理解你这个存在。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "I have been striving to understand you."
L27_1.m_Talk_DEU = L28_1
L28_1 = "I have been striving to understand you."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP13_ACT3_INTERLUDE1@146#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 601
L28_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L29_1 = "왜냐하면 당신이란 존재는 모든 세계를 통틀어, 제가 이해할 수 없는 유일한 미지니까요."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "なぜなら、あなたという存在は全世界でただひとつ、私が理解できない未知の存在だからです。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Because you are the only unknown that I could not comprehend across all worlds."
L28_1.m_Talk_ENG = L29_1
L29_1 = "因為在所有世界中，唯有你是我無法理解的未知。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "因为在所有世界中，唯有你是我无法理解的未知。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Because you are the only unknown that I could not comprehend across all worlds."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Because you are the only unknown that I could not comprehend across all worlds."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
