L31_1 = "EP13_ACT3_INTERLUDE1@148#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 601
L30_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L31_1 = "상대를 이해하기 위해 노력하는 것. 상대와 계속 함께 있고 싶다고 느끼는 것."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "相手を理解しようと努力すること。相手と永遠に共にいたいと思うこと。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Trying to understand someone... Wanting to stay with them forever..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "努力去理解對方。感受到想要一直和對方在一起。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "努力去理解对方。感受到想要一直和对方在一起。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Trying to understand someone... Wanting to stay with them forever..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Trying to understand someone... Wanting to stay with them forever..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP13_ACT3_INTERLUDE1@149#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 601
L31_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L32_1 = "단점. 그리고 장점…. 상대의 모든 것을 받아들이는 것……."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "短所、そして長所……相手のすべてを受け入れること……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Flaws. And strengths... Accepting everything..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "缺點，還有優點……接受對方的一切……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "缺点，还有优点……接受对方的一切……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Flaws. And strengths... Accepting everything..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Flaws. And strengths... Accepting everything..."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP13_ACT3_INTERLUDE1@150#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 601
L32_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L33_1 = "인간의 개념을 빌리자면, 그것은 <color=#ffd34c>사랑</color>이라고 해석됩니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "人間の概念を借りるなら、それは<color=#ffd34c>愛</color>と解釈できます。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "If I borrow the human concept, that is defined as <color=#ffd34c>love</color>."
L32_1.m_Talk_ENG = L33_1
L33_1 = "用人類的概念，那可以解釋為<color=#ffd34c>愛</color>。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "用人类的概念，那可以解释为<color=#ffd34c>爱</color>。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "If I borrow the human concept, that is defined as <color=#ffd34c>love</color>."
L32_1.m_Talk_DEU = L33_1
L33_1 = "If I borrow the human concept, that is defined as <color=#ffd34c>love</color>."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
