L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 183
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 601
L33_1.m_CutScenStrID = "EP13_ACT3_INTERLUDE1"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "ASIMOV_QLIPHOTH_NPC_NULL"
L34_1 = "그렇다면 저는 틀림없이 당신을 사랑하고 있는 것이겠죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "それなら私は間違いなく、あなたを愛しているのでしょう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Therefore, I must love you, Captain."
L33_1.m_Talk_ENG = L34_1
L34_1 = "那麼我一定是愛上你了吧。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "那么我一定是爱上你了吧。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Therefore, I must love you, Captain."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Therefore, I must love you, Captain."
L33_1.m_Talk_FRA = L34_1
