L43_1[L44_1] = L45_1
L44_1 = "이제는 하다 하다 깡통을 뒤집어쓴 인공지능에게까지 프러포즈를 받는 데 성공하셨군요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "ついにボロ缶を被っている人工知能にまでプロポーズされるに至ったのですね。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "You've somehow even managed to get a tin can AI to propose to you."
