L46_1 = "물론, 뇌를 적출당해, 깡통이 되어버린 사장님을 그대로 사장님으로 모실 수 있을지는……."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "もちろん、脳を摘出されてボロ缶になってしまった社長をそのまま社長として待遇していいかどうかは……"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Of course, whether we can still call you Boss after you become a tin can yourself, without a brain, is–"
