L12_1 = "깡통 주제에 제법 로맨틱한 표현을 쓰긴 했지만, 사실상 전 인류의 목숨을 건 협박입니다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ボロ缶のくせになかなかロマンチックな表現を使いましたが、実際、あれは全人類の命をかけた脅迫ですからね。"
L11_1.m_Talk_JPN = L12_1
